+/* SmartDiffViewer — grouped-by-risk diff (core/wiring/boilerplate), a sibling
+   to the flat DiffViewer (not a replacement — DiffTab's "Original order"
+   toggle still needs the flat view). Renders `SmartDiff.groups[]` in the
+   order the server already returns them, reusing FileCard for each file's
+   collapsible patch view.
+
+   Phase 5 — `pseudocode_summary` renders in TWO spots: a "Summary" Chip on
+   the file's header row (visible collapsed, alongside the findings Chip in
+   the same `headerRight` slot) and the "What this does: …" text block
+   FileCard itself renders below its header once open.
+
+   Phase 6 — a `split_suggestion` banner (rendered only when `too_big`),
+   above the group list: one clickable Chip per `ProposedSplit`. Clicking a
+   split's Chip highlights that split's files by dimming every OTHER
+   rendered `FileCard` (via its new `dimmed` prop), opens the `core` section
+   if it was collapsed (every split file is always `core`-role —
+   server/src/modules/smart-diff/service.ts only ever feeds `coreFilePaths`
+   into the clusterer), and scrolls the split's first file into view —
+   otherwise, on a long PR, telling which file just got highlighted means
+   scrolling/hunting for it manually. Clicking the same Chip again clears
+   the highlight (no re-scroll). Suggestion/highlight surface only — no PR
+   is actually created or split here. */
+"use client";
+
+import React from "react";
+import { useTranslations } from "next-intl";
+import { Icon, Chip } from "@devdigest/ui";
+import type { PrFile } from "@/lib/types";
+import type { SmartDiff, SmartDiffRole } from "@devdigest/shared";
+import { type DiffCommentApi } from "../comments";
+import { chevronFor } from "../styles";
+import { AUTO_EXPAND_MAX_LINES } from "../constants";
+import { FileCard } from "../FileCard";
+import type { ScrollTarget } from "../helpers";
+import { ROLE_COLORS, DEFAULT_SECTION_OPEN } from "./constants";
+import { s } from "./styles";
+
+/** The currently-highlighted proposed split (Phase 6) — `index` (not just
+ *  `files`) is tracked so clicking the SAME Chip twice can be detected and
+ *  toggled off, even if two splits happened to have identical `files`. */
+interface HighlightedSplit {
+  index: number;
+  files: string[];
+}
+
+export function SmartDiffViewer({
+  smartDiff,
+  files,
+  commenting,
+  scrollTarget: externalScrollTarget,
+}: {
+  smartDiff: SmartDiff;
+  files: PrFile[];
+  commenting?: DiffCommentApi;
+  /** An external "view in diff" request (Findings tab) — distinct from this
+   *  component's own internal, findings-Chip-click-driven scroll target. On
+   *  the same file, the internal target wins (see the merge below). */
+  scrollTarget?: ScrollTarget | null;
+}) {
+  const t = useTranslations("prReview");
+  // `SmartDiffFile` carries no `patch` — build the lookup once so each
+  // classified file can hand its full row to `FileCard`.
+  const fileMap = React.useMemo(() => new Map(files.map((f) => [f.path, f])), [files]);
+  // Path → role lookup, used to force-open the right section when an
+  // external scroll target lands on a file in a currently-collapsed group.
+  const roleByPath = React.useMemo(() => {
+    const m = new Map<string, SmartDiffRole>();
+    for (const g of smartDiff.groups) for (const f of g.files) m.set(f.path, g.role);
+    return m;
+  }, [smartDiff]);
+  const [openSections, setOpenSections] =
+    React.useState<Record<SmartDiffRole, boolean>>(DEFAULT_SECTION_OPEN);
+  const [internalScrollTarget, setInternalScrollTarget] = React.useState<ScrollTarget | null>(null);
+  const [highlightedSplit, setHighlightedSplit] = React.useState<HighlightedSplit | null>(null);
+  const [splitScrollNonce, setSplitScrollNonce] = React.useState(0);
+  const listRef = React.useRef<HTMLDivElement | null>(null);
+
+  const { too_big: tooBig, total_lines: totalLines, proposed_splits: proposedSplits } =
+    smartDiff.split_suggestion;
+
+  // Force-open the containing section when an external scroll target
+  // arrives for a file in a currently-collapsed group — mirrors the
+  // split-highlight Chip's own setOpenSections call above.
+  React.useEffect(() => {
+    if (!externalScrollTarget) return;
+    const role = roleByPath.get(externalScrollTarget.path);
+    if (!role) return; // missing-file degrade: no section to open, no-op
+    setOpenSections((prev) => (prev[role] ? prev : { ...prev, [role]: true }));
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, [externalScrollTarget?.nonce]);
+
+  // Bringing the highlighted split's first file into view needs the `core`
+  // section open AND the FileCard actually mounted first — both the section
+  // toggle above and this file's own `open` state (driven by `defaultOpen`)
+  // land on the next render, so this can't just scrollIntoView synchronously
+  // inside the click handler.
+  React.useEffect(() => {
+    if (splitScrollNonce === 0 || !highlightedSplit) return;
+    const target = highlightedSplit.files[0];
+    if (!target) return;
+    const el = Array.from(listRef.current?.querySelectorAll<HTMLElement>("[data-file]") ?? []).find(
+      (node) => node.getAttribute("data-file") === target,
+    );
+    el?.scrollIntoView({ behavior: "smooth", block: "center" });
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, [splitScrollNonce]);
+
+  return (
+    <div style={s.list} ref={listRef}>
+      {tooBig && (
+        <div style={s.splitBanner}>
+          <div style={s.splitBannerTitle}>{t("smartDiff.largeTitle", { lines: totalLines })}</div>
+          <div style={s.splitBannerBody}>{t("smartDiff.largeBody")}</div>
+          <div style={s.splitChips}>
+            {proposedSplits.map((split, index) => (
+              <Chip
+                key={`${split.name}-${index}`}
+                active={highlightedSplit?.index === index}
+                onClick={() => {
+                  if (highlightedSplit?.index === index) {
+                    setHighlightedSplit(null);
+                    return;
+                  }
+                  setOpenSections((prev) => ({ ...prev, core: true }));
+                  setHighlightedSplit({ index, files: split.files });
+                  setSplitScrollNonce((n) => n + 1);
+                }}
+              >
+                {split.name} · {t("smartDiff.filesCount", { count: split.files.length })}
+              </Chip>
+            ))}
+          </div>
+        </div>
+      )}
+      {smartDiff.groups.map((group) => {
+        const isOpen = openSections[group.role];
+        return (
+          <div key={group.role} style={s.section}>
+            <button
+              type="button"
+              style={s.sectionHeader}
+              aria-expanded={isOpen}
+              onClick={() =>
+                setOpenSections((prev) => ({ ...prev, [group.role]: !prev[group.role] }))
+              }
+            >
+              <Icon.ChevronRight size={13} style={chevronFor(isOpen)} />
+              <span
+                data-role-dot={group.role}
+                style={{ ...s.roleDot, backgroundColor: ROLE_COLORS[group.role] }}
+              />
+              <span style={s.roleTitle}>{t(`smartDiff.${group.role}Label`)}</span>
+              <span style={s.roleDescription}>{t(`smartDiff.${group.role}Description`)}</span>
+              <span style={s.roleFileCount}>
+                {t("smartDiff.filesCount", { count: group.files.length })}
+              </span>
+            </button>
+            {isOpen && (
+              <div style={s.sectionBody}>
+                {group.files.map((file) => {
+                  const prFile = fileMap.get(file.path);
+                  if (!prFile) return null;
+                  const defaultOpen =
+                    group.role !== "boilerplate" &&
+                    (file.findings_count > 0 ||
+                      file.additions + file.deletions <= AUTO_EXPAND_MAX_LINES);
+                  const findingSeverityByLine = new Map(
+                    file.finding_lines.map((f) => [f.line, f.severity]),
+                  );
+                  // Internal and external each keep their own independent
+                  // nonce counter (both start at 1) — remapped here to
+                  // disjoint parities (internal always even, external always
+                  // odd) so the merged nonce FileCard actually receives can
+                  // never numerically collide between the two sources,
+                  // regardless of their raw counter values. Without this, a
+                  // first-ever internal click right after a first-ever
+                  // external arrival on the SAME file could reuse the same
+                  // raw nonce number and FileCard's scroll effect (keyed on
+                  // scrollToLine.nonce) wouldn't re-fire even though the
+                  // winning line changed.
+                  const internalTarget =
+                    internalScrollTarget && internalScrollTarget.path === file.path
+                      ? { line: internalScrollTarget.line, nonce: internalScrollTarget.nonce * 2 }
+                      : undefined;
+                  const externalTarget =
+                    externalScrollTarget && externalScrollTarget.path === file.path
+                      ? { line: externalScrollTarget.line, nonce: externalScrollTarget.nonce * 2 + 1 }
+                      : undefined;
+                  // Internal (this file's own findings-Chip click) wins over
+                  // an external "view in diff" request landing on the same
+                  // file — don't clobber the user's current in-page target.
+                  const scrollToLine = internalTarget ?? externalTarget;
+                  const findingsChip = file.findings_count > 0 && (
+                    <Chip
+                      onClick={() =>
+                        setInternalScrollTarget((prev) => ({
+                          path: file.path,
+                          line: file.finding_lines[0]!.line,
+                          nonce: (prev?.nonce ?? 0) + 1,
+                        }))
+                      }
+                    >
+                      {t("verdict.findingsCount", { count: file.findings_count })}
+                    </Chip>
+                  );
+                  const summaryChip = file.pseudocode_summary != null && (
+                    <Chip icon="Info">{t("smartDiff.summaryLabel")}</Chip>
+                  );
+                  const headerRight = (findingsChip || summaryChip) && (
+                    <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
+                      {findingsChip}
+                      {summaryChip}
+                    </span>
+                  );
+                  const dimmed =
+                    highlightedSplit != null && !highlightedSplit.files.includes(file.path);
+                  return (
+                    <FileCard
+                      key={file.path}
+                      file={prFile}
+                      commenting={commenting}
+                      defaultOpen={defaultOpen}
+                      scrollToLine={scrollToLine}
+                      findingSeverityByLine={findingSeverityByLine}
+                      headerRight={headerRight || undefined}
+                      pseudocodeSummary={file.pseudocode_summary}
+                      dimmed={dimmed}
+                    />
+                  );
+                })}
+              </div>
+            )}
+          </div>
+        );
+      })}
+    </div>
+  );
+}

