+    const parsed = (req.schema as z.ZodType<T>).safeParse(fixture);
+    if (!parsed.success) throw new Error(`PerAgentMockLLM fixture failed schema: ${parsed.error.message}`);
+    return {
+      data: parsed.data,
+      model: req.model,
+      tokensIn: 100,
+      tokensOut: 50,
+      costUsd: 0.001,
+      raw: JSON.stringify(fixture),
+      attempts: 1,
